description:
Pass button props with `actionProps` to render an action.

```tsx
const id = toast.add({
  id: "event-created",
  title: "Event created",
  actionProps: {
    children: "Undo",
    onClick() {
      toast.close(id);
    },
  },
});
```

files.content:
import { Button } from "@/registry/erbium/ui/button";
import { toast } from "@/registry/erbium/ui/toast";

const Example = () => (
  <Button
    onClick={() =>
      toast.add({
        title: "Draft saved",
        actionProps: {
          children: "Undo",
          onClick: () => toast.add({ title: "Draft restored" }),
        },
      })
    }
  >
    Show action toast
  </Button>
);

export default Example;
